#include <SPI.h>
#include <TFT_eSPI.h>

// XIAO ESP32S3のピン配置定義
#define TFT_MOSI 10  // D10
#define TFT_SCLK 8   // D8
#define TFT_CS   4   // D3
#define TFT_DC   3   // D2
#define TFT_RST  2   // D1

// インスタンスの作成
TFT_eSPI tft = TFT_eSPI();

void setup() {
  Serial.begin(115200);

  // 液晶の初期化
  tft.init();

  // 画面の向きを設定 (0〜3)
  tft.setRotation(1);

  // 画面を黒色でクリア
  tft.fillScreen(TFT_BLACK);

  // テキストの設定と表示
  tft.setTextColor(TFT_WHITE, TFT_BLACK); // 文字色:白、背景色:黒
  tft.setTextSize(2);                     // 文字サイズ
  tft.setCursor(10, 20);                  // 表示位置 (X, Y)
  tft.println("XIAO ESP32S3");

  tft.setTextColor(TFT_GREEN, TFT_BLACK);
  tft.setCursor(10, 50);
  tft.println("ST7735 Test");

  // グラフィックの描画テスト
  tft.drawRect(5, 5, 150, 118, TFT_BLUE); // 青い枠線
}

void loop() {
  // テスト用に色を反転させるループ（動作確認用）
  tft.setTextColor(TFT_RED, TFT_BLACK);
  tft.setCursor(10, 80);
  tft.print("Status: OK ");
  delay(500);

  tft.setTextColor(TFT_YELLOW, TFT_BLACK);
  tft.setCursor(10, 80);
  tft.print("Status: OK*");
  delay(500);
}
